//! Licence verification and entitlements.
//!
//! This build can only *verify*: the signing key lives with the vendor, and the
//! matching public key is compiled in here.

use ed25519_dalek::{Signature, Verifier, VerifyingKey};
use ledgerly_license::{License, LicenseFile, FORMAT_VERSION};
use serde::Serialize;

use crate::error::{AppError, AppResult};

/// The vendor's public key. Generated by `tools/licensectl`; replace the dev key
/// with your own before shipping.
const EMBEDDED_PUBLIC_KEY: &str = include_str!("../../assets/license_public_key.txt");

/// Everything a Pro licence unlocks. Security features (app lock, encryption)
/// are deliberately *not* on this list — they stay free.
pub const PRO_FEATURES: &[&str] = &[
    "reports",
    "pdf_templates",
    "branding",
    "scheduled_backups",
    "batch_export",
    "multi_currency",
];

#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Entitlements {
    pub licensed: bool,
    /// `free`, `license` or `trial`.
    pub source: String,
    pub plan: Option<String>,
    pub features: Vec<String>,
    pub expires_at: Option<String>,
}

impl Entitlements {
    pub fn free() -> Entitlements {
        Entitlements {
            licensed: false,
            source: "free".to_string(),
            plan: None,
            features: Vec::new(),
            expires_at: None,
        }
    }

    pub fn trial(ends_at: String) -> Entitlements {
        Entitlements {
            licensed: true,
            source: "trial".to_string(),
            plan: Some("trial".to_string()),
            features: PRO_FEATURES.iter().map(|name| (*name).to_string()).collect(),
            expires_at: Some(ends_at),
        }
    }

    /// Unknown features are always denied.
    pub fn allows(&self, feature: &str) -> bool {
        self.licensed && self.features.iter().any(|name| name == feature)
    }
}

pub fn embedded_key() -> AppResult<VerifyingKey> {
    let bytes = ledgerly_license::unhex(EMBEDDED_PUBLIC_KEY.trim()).ok_or_else(|| {
        AppError::Validation("This build has no licence public key.".to_string())
    })?;
    let key: [u8; 32] = bytes.try_into().map_err(|_| {
        AppError::Validation("The embedded licence public key is malformed.".to_string())
    })?;
    VerifyingKey::from_bytes(&key)
        .map_err(|_| AppError::Validation("The embedded licence public key is invalid.".to_string()))
}

pub fn parse_file(text: &str) -> AppResult<LicenseFile> {
    serde_json::from_str(text).map_err(|_| {
        AppError::Validation("That does not look like a Ledgerly licence file.".to_string())
    })
}

/// Check a licence against a specific public key, binding and date.
pub fn verify_with_key(
    file: &LicenseFile,
    key: &VerifyingKey,
    expected_binding: &str,
    today: &str,
) -> AppResult<License> {
    let signature = ledgerly_license::unhex(&file.signature)
        .ok_or_else(|| AppError::Validation("The licence signature is malformed.".to_string()))?;
    let signature: [u8; 64] = signature.try_into().map_err(|_| {
        AppError::Validation("The licence signature is the wrong length.".to_string())
    })?;

    key.verify(
        &file.license.signing_bytes(),
        &Signature::from_bytes(&signature),
    )
    .map_err(|_| {
        AppError::Validation(
            "This licence key is not valid — the signature does not match.".to_string(),
        )
    })?;

    if file.license.version > FORMAT_VERSION {
        return Err(AppError::Validation(format!(
            "This licence uses a newer format ({}).",
            file.license.version
        )));
    }

    if file.license.binding != expected_binding {
        return Err(AppError::Validation(
            "This licence was issued for a different installation or machine.".to_string(),
        ));
    }

    if let Some(expires_at) = &file.license.expires_at {
        if expires_at.as_str() < today {
            return Err(AppError::Validation(format!(
                "This licence expired on {expires_at}."
            )));
        }
    }

    Ok(file.license.clone())
}

/// Verify against the key compiled into this build.
pub fn verify(file: &LicenseFile, expected_binding: &str, today: &str) -> AppResult<License> {
    verify_with_key(file, &embedded_key()?, expected_binding, today)
}

#[cfg(test)]
mod tests {
    use super::*;
    use ed25519_dalek::{Signer, SigningKey};

    fn keypair() -> SigningKey {
        SigningKey::from_bytes(&[42u8; 32])
    }

    fn ticket(binding: &str, expires_at: Option<&str>) -> LicenseFile {
        let license = License {
            version: FORMAT_VERSION,
            key_id: "test".to_string(),
            sku: "ledgerly".to_string(),
            plan: if expires_at.is_some() { "term" } else { "perpetual" }.to_string(),
            features: vec!["reports".to_string()],
            issued_at: "2026-01-01".to_string(),
            expires_at: expires_at.map(str::to_string),
            binding: binding.to_string(),
        };

        let signature = keypair().sign(&license.signing_bytes());
        LicenseFile {
            license,
            signature: ledgerly_license::hex(&signature.to_bytes()),
        }
    }

    #[test]
    fn a_matching_licence_verifies() {
        let file = ticket("bind-1", None);
        let license = verify_with_key(&file, &keypair().verifying_key(), "bind-1", "2026-10-09")
            .unwrap();
        assert_eq!(license.features, vec!["reports"]);
    }

    #[test]
    fn the_embedded_key_parses() {
        // Guards against shipping a build with a broken or placeholder key.
        assert!(embedded_key().is_ok());
    }

    #[test]
    fn a_tampered_licence_is_rejected() {
        let mut file = ticket("bind-1", None);
        file.license.features.push("branding".to_string());

        let error = verify_with_key(&file, &keypair().verifying_key(), "bind-1", "2026-10-09")
            .unwrap_err()
            .to_string();
        assert!(error.contains("signature does not match"), "got: {error}");
    }

    #[test]
    fn a_licence_for_another_machine_is_rejected() {
        let file = ticket("other-machine", None);
        let error = verify_with_key(&file, &keypair().verifying_key(), "bind-1", "2026-10-09")
            .unwrap_err()
            .to_string();
        assert!(error.contains("different installation"), "got: {error}");
    }

    #[test]
    fn an_expired_licence_is_rejected() {
        let file = ticket("bind-1", Some("2026-01-01"));
        let error = verify_with_key(&file, &keypair().verifying_key(), "bind-1", "2026-10-09")
            .unwrap_err()
            .to_string();
        assert!(error.contains("expired"), "got: {error}");

        // ...but is fine the day before it expires.
        assert!(verify_with_key(&file, &keypair().verifying_key(), "bind-1", "2025-12-31").is_ok());
    }

    #[test]
    fn a_signature_from_another_key_is_rejected() {
        let file = ticket("bind-1", None);
        let stranger = SigningKey::from_bytes(&[9u8; 32]);
        assert!(
            verify_with_key(&file, &stranger.verifying_key(), "bind-1", "2026-10-09").is_err()
        );
    }

    #[test]
    fn entitlements_deny_by_default() {
        let free = Entitlements::free();
        assert!(!free.licensed);
        for feature in PRO_FEATURES {
            assert!(!free.allows(feature), "{feature} should not be free");
        }
        assert!(!free.allows("something_new"));

        let trial = Entitlements::trial("2026-11-01".to_string());
        assert!(trial.allows("reports"));
        assert!(!trial.allows("something_new"));
    }
}
